<script setup>
import { computed, ref, watch } from "vue";
const props = defineProps({ modelValue: { type: [String, Number], default: "" }, options: { type: Array, default: () => [] }, placeholder: { type: String, default: "Rechercher…" }, required: Boolean });
const emit = defineEmits(["update:modelValue"]); const open = ref(false); const query = ref("");
const selected = computed(() => props.options.find((option) => String(option.value) === String(props.modelValue)));
const filtered = computed(() => { const term = query.value.trim().toLowerCase(); return props.options.filter((option) => !term || option.label.toLowerCase().includes(term)); });
watch(() => props.modelValue, () => { if (!open.value) query.value = selected.value?.label || ""; }, { immediate: true });
function choose(option) { emit("update:modelValue", option.value); query.value = option.label; open.value = false; }
function clear() { emit("update:modelValue", ""); query.value = ""; open.value = true; }
function onFocus() { open.value = true; if (selected.value && query.value === selected.value.label) query.value = ""; }
</script>
<template><div class="search-select" @keydown.escape="open = false"><div class="input-wrap"><input v-model="query" :placeholder="placeholder" :required="required && !modelValue" autocomplete="off" @focus="onFocus" @input="open = true" /><button v-if="modelValue" type="button" class="clear" aria-label="Effacer" @click="clear">×</button><span class="chevron">⌄</span></div><div v-if="open" class="options"><button v-for="option in filtered" :key="option.value" type="button" :class="{ selected: String(option.value) === String(modelValue) }" @mousedown.prevent="choose(option)">{{ option.label }}</button><span v-if="!filtered.length" class="no-result">Aucun résultat</span></div></div></template>
<style scoped>.search-select{position:relative}.input-wrap{position:relative}.search-select input{width:100%;padding:.75rem 2.1rem .75rem .8rem;border:1px solid #dce4ef;border-radius:.5rem;outline:0;color:#30415a;background:#fff;font-size:.78rem}.search-select input:focus{border-color:#6d95eb;box-shadow:0 0 0 4px rgb(79 120 232 / 10%)}.chevron{position:absolute;top:50%;right:.75rem;color:#8c9aac;pointer-events:none;transform:translateY(-55%)}.clear{position:absolute;top:50%;right:1.6rem;padding:0;border:0;color:#9aa7b7;background:none;font-size:1rem;cursor:pointer;transform:translateY(-55%)}.options{position:absolute;z-index:30;top:calc(100% + .35rem);right:0;left:0;display:grid;max-height:14rem;overflow:auto;padding:.3rem;border:1px solid #dce4ef;border-radius:.55rem;background:#fff;box-shadow:0 12px 24px rgb(30 52 84 / 13%)}.options button{padding:.6rem .65rem;border:0;border-radius:.35rem;color:#53647c;background:#fff;text-align:left;font-size:.73rem;cursor:pointer}.options button:hover,.options button.selected{color:#315fc5;background:#eff4ff}.no-result{padding:.7rem;color:#9aa7b7;font-size:.72rem;text-align:center}</style>
